<!doctype html><html><head><meta charset="utf-8"><title>@yield('title')</title><style>body{font:13px/1.35 Arial,sans-serif;color:#000;margin:0;padding:8px}.print-doc{max-width:80mm;margin:auto}.center{text-align:center}.right{text-align:right}.line{border-top:1px dashed #000;margin:7px 0}table{width:100%;border-collapse:collapse}th,td{padding:3px 1px;vertical-align:top}th{border-bottom:1px solid #000}.big{font-size:26px;font-weight:800}.muted{font-size:11px}.no-print{margin:10px;text-align:center}@media print{.no-print{display:none}body{padding:0}@page{margin:4mm}}</style></head><body><div class="no-print"><button onclick="window.print()">Print</button></div><main class="print-doc">@yield('content')</main><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250));</script></body></html>
